refentry.refsect1:
  &reftitle.parameters;




     arrays


Merge गरिने arrays को variable list।

&reftitle.changelog;







     &Version;
     &Description;





     7.4.0
     यो function अब कुनै पनि parameter बिना call गर्न सकिन्छ। पहिले, कम्तीमा एउटा parameter आवश्यक पर्थ्यो।

  &reftitle.examples;



    array_merge को उदाहरण


<?php

$array1 = ["color" => "red", 2, 4];
$array2 = ["a", "b", "color" => "green", "shape" => "trapezoid", 4];

$result = array_merge($array1, $array2);

print_r($result);


    &example.outputs;


Array
(
    [color] => green
    [0] => 2
    [1] => 4
    [2] => a
    [3] => b
    [shape] => trapezoid
    [4] => 4
)







    array_merge को सरल उदाहरण


<?php

$array1 = [];
$array2 = [1 => "data"];

$result = array_merge($array1, $array2);

print_r($result);



numeric keys renumber हुनेछन् भनी नबिर्सनुहोस्!


Array
(
    [0] => data
)



यदि तपाईँ पहिलो array from का elements लाई overwrite नगरी र re-index नगरी, दोस्रो array from का array elements लाई पहिलो array मा append गर्न चाहनुहुन्छ भने, + array union operator प्रयोग गर्नुहोस्:


<?php

$array1 = [0 => 'zero_a', 2 => 'two_a', 3 => 'three_a'];
$array2 = [1 => 'one_b', 3 => 'three_b', 4 => 'four_b'];

$result = $array1 + $array2;

var_dump($result);



पहिलो array from का keys सुरक्षित रहनेछन्। यदि कुनै array key दुवै arrays मा छ भने, पहिलो array from को element प्रयोग गरिनेछ र दोस्रो array from को मिल्दो key को element लाई ignore गरिनेछ।


array(5) {
  [0]=>
  string(6) "zero_a"
  [2]=>
  string(5) "two_a"
  [3]=>
  string(7) "three_a"
  [1]=>
  string(5) "one_b"
  [4]=>
  string(6) "four_b"
}
